156	func spanToJaegerProto(span ptrace.Span, libraryTags pcommon.InstrumentationScope) *model.Span {
157		traceID := traceIDToJaegerProto(span.TraceID())
158		jReferences := makeJaegerProtoReferences(span.Links(), spanIDToJaegerProto(span.ParentSpanID()), traceID)
159	
160		startTime := span.StartTimestamp().AsTime()
161		return &model.Span{
162			TraceID:       traceID,
163			SpanID:        spanIDToJaegerProto(span.SpanID()),
164			OperationName: span.Name(),
165			References:    jReferences,
166			StartTime:     startTime,
167			Duration:      span.EndTimestamp().AsTime().Sub(startTime),
168			Tags:          getJaegerProtoSpanTags(span, libraryTags),
169			Logs:          spanEventsToJaegerProtoLogs(span.Events()),
170		}
171	}
