134	func dbTagsToAttributes(tags []dbmodel.KeyValue, attributes pcommon.Map) {
135		for _, tag := range tags {
136			tagValue, ok := tag.Value.(string)
137			if !ok {
138				switch tag.Type {
139				case dbmodel.Float64Type, dbmodel.Int64Type:
140					fromDBNumber(tag, attributes)
141				case dbmodel.BoolType:
142					v, ok := tag.Value.(bool)
143					if !ok {
144						recordTagInvalidTypeError(tag, attributes)
145					} else {
146						attributes.PutBool(tag.Key, v)
147					}
148				default:
149					// This means type is string/binary but value is of non string type, hence record the type error
150					recordTagInvalidTypeError(tag, attributes)
151				}
152				continue
153			}
154			switch tag.Type {
155			case dbmodel.StringType:
156				attributes.PutStr(tag.Key, tagValue)
157			case dbmodel.BoolType:
158				convBoolVal, err := strconv.ParseBool(tagValue)
159				if err != nil {
160					recordTagConversionError(tag, err, attributes)
161				} else {
162					attributes.PutBool(tag.Key, convBoolVal)
163				}
164			case dbmodel.Int64Type:
165				intVal, err := strconv.ParseInt(tagValue, 10, 64)
166				if err != nil {
167					recordTagConversionError(tag, err, attributes)
168				} else {
169					attributes.PutInt(tag.Key, intVal)
170				}
171			case dbmodel.Float64Type:
172				floatVal, err := strconv.ParseFloat(tagValue, 64)
173				if err != nil {
174					recordTagConversionError(tag, err, attributes)
175				} else {
176					attributes.PutDouble(tag.Key, floatVal)
177				}
178			case dbmodel.BinaryType:
179				value, err := hex.DecodeString(tagValue)
180				if err != nil {
181					recordTagConversionError(tag, err, attributes)
182				} else {
183					attributes.PutEmptyBytes(tag.Key).FromRaw(value)
184				}
185			default:
186				attributes.PutStr(tag.Key, fmt.Sprintf("<Unknown Jaeger TagType %q>", tag.Type))
187			}
188		}
189	}
