30	// ToDBModel translates internal trace data into the DB Spans.
31	// Returns slice of translated DB Spans and error if translation failed.
32	func ToDBModel(td ptrace.Traces) []dbmodel.Span {
33		resourceSpans := td.ResourceSpans()
34	
35		if resourceSpans.Len() == 0 {
36			return nil
37		}
38	
39		batches := make([]dbmodel.Span, 0, resourceSpans.Len())
40		for i := 0; i < resourceSpans.Len(); i++ {
41			rs := resourceSpans.At(i)
42			batch := resourceSpansToDbSpans(rs)
43			if batch != nil {
44				batches = append(batches, batch...)
45			}
46		}
47	
48		return batches
49	}
