51	func resourceSpansToDbSpans(resourceSpans ptrace.ResourceSpans) []dbmodel.Span {
52		resource := resourceSpans.Resource()
53		scopeSpans := resourceSpans.ScopeSpans()
54	
55		if scopeSpans.Len() == 0 {
56			return []dbmodel.Span{}
57		}
58	
59		process := resourceToDbProcess(resource)
60	
61		// Approximate the number of the spans as the number of the spans in the first
62		// instrumentation library info.
63		dbSpans := make([]dbmodel.Span, 0, scopeSpans.At(0).Spans().Len())
64	
65		for _, scopeSpan := range scopeSpans.All() {
66			for _, span := range scopeSpan.Spans().All() {
67				dbSpan := spanToDbSpan(span, scopeSpan.Scope(), process)
68				dbSpans = append(dbSpans, dbSpan)
69			}
70		}
71	
72		return dbSpans
73	}
