75	func resourceToDbProcess(resource pcommon.Resource) dbmodel.Process {
76		process := dbmodel.Process{}
77		attrs := resource.Attributes()
78		if attrs.Len() == 0 {
79			process.ServiceName = noServiceName
80			return process
81		}
82		tags := make([]dbmodel.KeyValue, 0, attrs.Len())
83		for key, attr := range attrs.All() {
84			if key == conventions.ServiceNameKey {
85				process.ServiceName = attr.AsString()
86				continue
87			}
88			tags = append(tags, attributeToDbTag(key, attr))
