101	func attributeToDbTag(key string, attr pcommon.Value) dbmodel.KeyValue {
102		var tag dbmodel.KeyValue
103		switch attr.Type() {
104		case pcommon.ValueTypeBytes:
105			tag = dbmodel.KeyValue{Key: key, Value: hex.EncodeToString(attr.Bytes().AsRaw())}
106		case pcommon.ValueTypeMap, pcommon.ValueTypeSlice:
107			tag = dbmodel.KeyValue{Key: key, Value: attr.AsString()}
108		default:
109			tag = dbmodel.KeyValue{Key: key, Value: attr.AsRaw()}
110		}
111		switch attr.Type() {
112		case pcommon.ValueTypeInt:
113			tag.Type = dbmodel.Int64Type
114		case pcommon.ValueTypeBool:
115			tag.Type = dbmodel.BoolType
116		case pcommon.ValueTypeDouble:
117			tag.Type = dbmodel.Float64Type
118		case pcommon.ValueTypeBytes:
119			tag.Type = dbmodel.BinaryType
120		default:
121			tag.Type = dbmodel.StringType
122		}
123		return tag
124	}
