145	func getDbSpanTags(span ptrace.Span, scope pcommon.InstrumentationScope) []dbmodel.KeyValue {
146		var spanKindTag, statusCodeTag, statusMsgTag dbmodel.KeyValue
147		var spanKindTagFound, statusCodeTagFound, statusMsgTagFound bool
148	
149		libraryTags, libraryTagsFound := getTagsFromInstrumentationLibrary(scope)
150	
151		tagsCount := span.Attributes().Len() + len(libraryTags)
152	
153		spanKindTag, spanKindTagFound = getTagFromSpanKind(span.Kind())
154		if spanKindTagFound {
155			tagsCount++
156		}
157		status := span.Status()
158		statusCodeTag, statusCodeTagFound = getTagFromStatusCode(status.Code())
159		if statusCodeTagFound {
160			tagsCount++
161		}
162	
163		statusMsgTag, statusMsgTagFound = getTagFromStatusMsg(status.Message())
164		if statusMsgTagFound {
165			tagsCount++
166		}
167	
168		traceStateTags, traceStateTagsFound := getTagsFromTraceState(span.TraceState().AsRaw())
169		if traceStateTagsFound {
170			tagsCount += len(traceStateTags)
171		}
172	
173		if tagsCount == 0 {
174			return nil
175		}
176	
177		tags := make([]dbmodel.KeyValue, 0, tagsCount)
178		if libraryTagsFound {
179			tags = append(tags, libraryTags...)
180		}
181		tags = appendTagsFromAttributes(tags, span.Attributes())
182		if spanKindTagFound {
183			tags = append(tags, spanKindTag)
184		}
185		if statusCodeTagFound {
186			tags = append(tags, statusCodeTag)
187		}
188		if statusMsgTagFound {
189			tags = append(tags, statusMsgTag)
190		}
191		if traceStateTagsFound {
192			tags = append(tags, traceStateTags...)
193		}
194		return tags
195	}
