197	// linksToDbSpanRefs constructs jaeger span references based on parent span ID and span links.
198	// The parent span ID is used to add a CHILD_OF reference, _unless_ it is referenced from one of the links.
199	func linksToDbSpanRefs(links ptrace.SpanLinkSlice, parentSpanID dbmodel.SpanID, traceID dbmodel.TraceID) []dbmodel.Reference {
200		refsCount := links.Len()
201		if parentSpanID != "" {
202			refsCount++
203		}
204	
205		if refsCount == 0 {
206			return nil
207		}
208	
209		refs := make([]dbmodel.Reference, 0, refsCount)
210	
211		// Put parent span ID at the first place because usually backends look for it
212		// as the first CHILD_OF item in the model.SpanRef slice.
213		if parentSpanID != "" {
214			refs = append(refs, dbmodel.Reference{
215				TraceID: traceID,
216				SpanID:  parentSpanID,
217				RefType: dbmodel.ChildOf,
218			})
219		}
220	
221		for i := 0; i < links.Len(); i++ {
222			link := links.At(i)
223			linkTraceID := dbmodel.TraceID(link.TraceID().String())
224			linkSpanID := dbmodel.SpanID(link.SpanID().String())
225			linkRefType := refTypeFromLink(link)
226			if parentSpanID != "" && linkTraceID == traceID && linkSpanID == parentSpanID {
227				// We already added a reference to this span, but maybe with the wrong type, so override.
228				refs[0].RefType = linkRefType
229				continue
230			}
231			refs = append(refs, dbmodel.Reference{
232				TraceID: linkTraceID,
233				SpanID:  linkSpanID,
234				RefType: linkRefType,
235			})
236		}
237	
238		return refs
239	}
